#!/usr/bin/env python3
import sys, os, socket, struct, random, time, json, ipaddress, ssl, urllib.parse, http.client

HELP = """dog ● command-line DNS client

Usage:
  dog [OPTIONS] [--] <arguments>

Examples:
  dog example.net                          Query a domain using default settings
  dog example.net MX                       ...looking up MX records instead
  dog example.net MX @1.1.1.1              ...using a specific nameserver instead
  dog example.net MX @1.1.1.1 -T           ...using TCP rather than UDP
  dog -q example.net -t MX -n 1.1.1.1 -T   As above, but using explicit arguments

Query options:
  <arguments>              Human-readable host names, nameservers, types, or classes
  -q, --query=HOST         Host name or domain name to query
  -t, --type=TYPE          Type of the DNS record being queried (A, MX, NS...)
  -n, --nameserver=ADDR    Address of the nameserver to send packets to
  --class=CLASS            Network class of the DNS record being queried (IN, CH, HS)

Sending options:
  --edns=SETTING           Whether to OPT in to EDNS (disable, hide, show)
  --txid=NUMBER            Set the transaction ID to a specific value
  -Z=TWEAKS                Set uncommon protocol-level tweaks

Protocol options:
  -U, --udp                Use the DNS protocol over UDP
  -T, --tcp                Use the DNS protocol over TCP
  -S, --tls                Use the DNS-over-TLS protocol
  -H, --https              Use the DNS-over-HTTPS protocol

Output options:
  -1, --short              Short mode: display nothing but the first result
  -J, --json               Display the output as JSON
  --color, --colour=WHEN   When to colourise the output (always, automatic, never)
  --seconds                Do not format durations, display them as seconds
  --time                   Print how long the response took to arrive

Meta options:
  -?, --help               Print list of command-line options
  -v, --version            Print version information"""

VERSION = """dog ● command-line DNS client
v0.2.0-pre [d3a34280] built on 2026-04-17 (pre-release!)
mhttps://dns.lookup.dog/"""

TYPE_CODES = {
    'A':1, 'NS':2, 'CNAME':5, 'SOA':6, 'PTR':12, 'HINFO':13, 'MX':15, 'TXT':16,
    'AAAA':28, 'LOC':29, 'SRV':33, 'NAPTR':35, 'OPT':41, 'DS':43, 'SSHFP':44,
    'TLSA':52, 'IXFR':251, 'AXFR':252, 'ANY':255, 'CAA':257, 'AFSDB':18, 'URI':256,
}
TYPE_NAMES = {v:k for k,v in TYPE_CODES.items()}
TYPE_NAMES.update({1:'A',2:'NS',5:'CNAME',6:'SOA',12:'PTR',13:'HINFO',15:'MX',16:'TXT',28:'AAAA',29:'LOC',33:'SRV',35:'NAPTR',41:'OPT',43:'DS',44:'SSHFP',52:'TLSA',251:'IXFR',252:'AXFR',255:'ANY',256:'URI',257:'CAA',18:'AFSDB'})
CLASS_CODES = {'IN':1, 'CH':3, 'HS':4}
CLASS_NAMES = {1:'IN', 3:'CH', 4:'HS'}
RCODE_TEXT = {1:'Format Error', 2:'Server Failure', 3:'NXDomain', 4:'Not Implemented', 5:'Query Refused', 6:'Name Exists when it should not', 7:'RR Set Exists when it should not', 8:'RR Set that should exist does not', 9:'Server Not Authoritative for zone', 10:'Name not contained in zone'}

class DogError(Exception):
    def __init__(self, msg, code=3):
        super().__init__(msg); self.code=code

class NetError(Exception):
    pass

class Options:
    def __init__(self):
        self.domains=[]; self.types=[]; self.classes=[]; self.nameservers=[]; self.transports=[]
        self.short=False; self.json=False; self.seconds=False; self.time=False; self.color='automatic'
        self.edns='hide'; self.txid=None; self.tweaks={'aa':False,'ad':False,'cd':False,'bufsize':None}


def fail(msg, code=3):
    raise DogError(msg, code)

def parse_type(s):
    up=s.upper()
    if up == 'OPT':
        fail('OPT request is sent by default (see -Z flag)')
    if up in TYPE_CODES and up != 'OPT': return TYPE_CODES[up]
    if s.isdigit():
        n=int(s)
        if 0 <= n <= 65535: return n
    fail(f'Invalid query type "{s}"')

def parse_class(s):
    up=s.upper()
    if up in CLASS_CODES: return CLASS_CODES[up]
    if s.isdigit():
        n=int(s)
        if 0 <= n <= 65535: return n
    fail(f'Invalid query class "{s}"')

def add_plain(opt, arg):
    if arg.startswith('@'):
        opt.nameservers.append(arg[1:]); return
    up=arg.upper()
    if up in CLASS_CODES or arg.isdigit():
        # Ambiguous numbers are classes only when explicitly class-looking? Original treats numeric plain as type? Avoid using numeric plain class.
        if up in CLASS_CODES:
            opt.classes.append(parse_class(arg)); return
    if up in TYPE_CODES or arg.isdigit():
        opt.types.append(parse_type(arg)); return
    if arg.startswith('-'):
        fail(f'Invalid domain "{arg}"')
    opt.domains.append(arg)

def need_arg(args, i, name):
    if i+1 >= len(args): fail(f"Argument to option '{name}' missing")
    return args[i+1], i+1

def parse_args(argv):
    opt=Options(); plain_mode=False; i=0
    while i < len(argv):
        a=argv[i]
        if plain_mode:
            add_plain(opt,a); i+=1; continue
        if a == '--':
            plain_mode=True; i+=1; continue
        if a in ('--help','-?'):
            print(HELP); sys.exit(0)
        if a in ('--version','-v'):
            print(VERSION); sys.exit(0)
        if a.startswith('--help='):
            fail("Option 'help' does not take an argument")
        if a.startswith('--version='):
            fail("Option 'version' does not take an argument")
        if a.startswith('--'):
            if '=' in a:
                name,val=a[2:].split('=',1)
            else:
                name=a[2:]; val=None
            def getv():
                nonlocal i, val
                if val is not None: return val
                v, ni = need_arg(argv, i, name); i=ni; return v
            if name=='query': opt.domains.append(getv())
            elif name=='type': opt.types.append(parse_type(getv()))
            elif name=='nameserver': opt.nameservers.append(getv())
            elif name=='class': opt.classes.append(parse_class(getv()))
            elif name=='edns':
                v=getv()
                if v not in ('disable','hide','show'): fail(f'Invalid EDNS setting "{v}"')
                opt.edns=v
            elif name=='txid':
                if opt.txid is not None: fail("Option 'txid' given more than once")
                v=getv()
                if not v.isdigit() or not (0 <= int(v) <= 65535): fail(f'Invalid transaction ID "{v}"')
                opt.txid=int(v)
            elif name in ('color','colour'):
                opt.color=getv()
            elif name=='udp': opt.transports.append('udp')
            elif name=='tcp': opt.transports.append('tcp')
            elif name=='tls': opt.transports.append('tls')
            elif name=='https': opt.transports.append('https')
            elif name=='short': opt.short=True
            elif name=='json': opt.json=True
            elif name=='seconds': opt.seconds=True
            elif name=='time': opt.time=True
            else:
                fail(f"Unrecognized option: '{name}'")
            i+=1; continue
        if a.startswith('-') and a != '-':
            j=1
            while j < len(a):
                ch=a[j]
                if ch in ('q','t','n','Z'):
                    if j+1 < len(a):
                        val=a[j+1:]; j=len(a)
                    else:
                        val, ni = need_arg(argv, i, ch); i=ni; j=len(a)
                    if ch=='q': opt.domains.append(val)
                    elif ch=='t': opt.types.append(parse_type(val))
                    elif ch=='n': opt.nameservers.append(val)
                    elif ch=='Z': parse_tweak(opt, val)
                    break
                elif ch=='U': opt.transports.append('udp')
                elif ch=='T': opt.transports.append('tcp')
                elif ch=='S': opt.transports.append('tls')
                elif ch=='H': opt.transports.append('https')
                elif ch=='1': opt.short=True
                elif ch=='J': opt.json=True
                elif ch=='?': print(HELP); sys.exit(0)
                elif ch=='v': print(VERSION); sys.exit(0)
                else: fail(f"Unrecognized option: '{ch}'")
                j+=1
            i+=1; continue
        add_plain(opt,a); i+=1
    if not opt.domains:
        print(HELP); sys.exit(3)
    if not opt.types: opt.types=[1]
    if not opt.classes: opt.classes=[1]
    if not opt.nameservers: opt.nameservers=['__system__']
    if not opt.transports: opt.transports=['udp']
    return opt

def parse_tweak(opt, v):
    if v=='aa': opt.tweaks['aa']=True
    elif v=='ad': opt.tweaks['ad']=True
    elif v=='cd': opt.tweaks['cd']=True
    elif v.startswith('bufsize='):
        n=v[8:]
        if not n.isdigit(): fail(f'Invalid protocol tweak "{v}"')
        opt.tweaks['bufsize']=int(n)
    else: fail(f'Invalid protocol tweak "{v}"')

# DNS wire helpers

def normalize_name(name):
    if name is None: return ''
    parts=[p for p in str(name).split('.') if p!='']
    if not parts: return ''
    return '.'.join(parts)+'.'

def wire_name(name):
    parts=[p for p in normalize_name(name).rstrip('.').split('.') if p]
    out=b''
    for p in parts:
        b=p.encode('utf-8')
        if len(b)>63: fail(f'Invalid domain "{name}"')
        out += bytes([len(b)]) + b
    return out + b'\x00'

def read_name(data, off, depth=0):
    if depth > 30: raise ValueError('compression loop')
    labels=[]; jumped=False; orig=off
    while True:
        if off >= len(data): raise ValueError('name out of bounds')
        l=data[off]
        if l & 0xc0 == 0xc0:
            if off+1>=len(data): raise ValueError('bad ptr')
            ptr=((l & 0x3f)<<8) | data[off+1]
            if not jumped: orig=off+2
            sub,_=read_name(data, ptr, depth+1)
            if sub: labels.extend(sub.rstrip('.').split('.'))
            off=orig; jumped=True; break
        off+=1
        if l==0: break
        if off+l > len(data): raise ValueError('label out of bounds')
        labels.append(data[off:off+l].decode('utf-8','replace'))
        off += l
    return ('.'.join([x for x in labels if x!='']) + ('.' if labels else ''), off)

def read_char_strings(data, off, end):
    arr=[]
    while off < end:
        ln=data[off]; off+=1
        arr.append(data[off:off+ln].decode('utf-8','replace'))
        off += ln
    return arr, off

def build_query(domain, qtype, qclass, opt):
