    name, off = read_name(data, off)
    if off+10 > len(data): raise ValueError('record truncated')
    typ, cls, ttl, rdlen = struct.unpack('!HHIH', data[off:off+10]); off += 10
    rstart=off; rend=off+rdlen; rdata=data[rstart:rend]
    if rend > len(data): raise ValueError('rdata truncated')
    parsed={'kind':'raw','bytes':list(rdata)}
    try:
        if typ == 1 and len(rdata)==4:
            parsed={'kind':'A','address':str(ipaddress.IPv4Address(rdata))}
        elif typ == 28 and len(rdata)==16:
            parsed={'kind':'AAAA','address':str(ipaddress.IPv6Address(rdata))}
        elif typ == 5:
            d,_=read_name(data,rstart); parsed={'kind':'CNAME','domain':d}
        elif typ == 2:
            d,_=read_name(data,rstart); parsed={'kind':'NS','nameserver':d}
        elif typ == 12:
            d,_=read_name(data,rstart); parsed={'kind':'PTR','cname':d}
        elif typ == 15 and rdlen>=2:
            pref=struct.unpack('!H', data[rstart:rstart+2])[0]; ex,_=read_name(data,rstart+2); parsed={'kind':'MX','preference':pref,'exchange':ex}
        elif typ == 6:
            p=rstart; m,p=read_name(data,p); r,p=read_name(data,p)
            vals=struct.unpack('!IIIII', data[p:p+20]) if p+20<=rend else (0,0,0,0,0)
            parsed={'kind':'SOA','mname':m,'rname':r,'serial':vals[0],'refresh':vals[1],'retry':vals[2],'expire':vals[3],'minimum':vals[4]}
        elif typ == 33 and rdlen>=6:
            pri,wei,port=struct.unpack('!HHH', data[rstart:rstart+6]); target,_=read_name(data,rstart+6)
            parsed={'kind':'SRV','priority':pri,'weight':wei,'port':port,'target':target}
        elif typ == 16:
            msgs,_=read_char_strings(data,rstart,rend); parsed={'kind':'TXT','messages':msgs}
        elif typ == 257 and rdlen>=2:
            flags=data[rstart]; tl=data[rstart+1]; tag=data[rstart+2:rstart+2+tl].decode('utf-8','replace'); val=data[rstart+2+tl:rend].decode('utf-8','replace')
            parsed={'kind':'CAA','critical':bool(flags & 0x80),'tag':tag,'value':val}
        elif typ == 44 and rdlen>=2:
            parsed={'kind':'SSHFP','algorithm':rdata[0],'fingerprint_type':rdata[1],'fingerprint':rdata[2:].hex()}
        elif typ == 52 and rdlen>=3:
            parsed={'kind':'TLSA','certificate_usage':rdata[0],'selector':rdata[1],'matching_type':rdata[2],'certificate_data':rdata[3:].hex()}
        elif typ == 13:
            msgs,_=read_char_strings(data,rstart,rend); parsed={'kind':'HINFO','cpu':msgs[0] if len(msgs)>0 else '', 'os':msgs[1] if len(msgs)>1 else ''}
        elif typ == 35 and rdlen>=4:
            p=rstart; order,pref=struct.unpack('!HH', data[p:p+4]); p+=4
            ss,p=read_char_strings(data,p,p+data[p]+1) if p<rend else ([''],p)
            flags_s=ss[0] if ss else ''
            ss,p=read_char_strings(data,p,p+data[p]+1) if p<rend else ([''],p)
            service=ss[0] if ss else ''
            ss,p=read_char_strings(data,p,p+data[p]+1) if p<rend else ([''],p)
            regex=ss[0] if ss else ''
            repl,_=read_name(data,p)
            parsed={'kind':'NAPTR','order':order,'preference':pref,'flags':flags_s,'service':service,'regex':regex,'replacement':repl}
        elif typ == 29 and rdlen>=16:
            version, size, hp, vp = rdata[0], rdata[1], rdata[2], rdata[3]
            lat,lon,alt=struct.unpack('!III', rdata[4:16])
            parsed={'kind':'LOC','version':version,'size_byte':size,'hp':hp,'vp':vp,'lat':lat,'lon':lon,'alt':alt}
        elif typ == 41:
            # OPT: class is UDP payload size; ttl encodes ext rcode/version/flags
            parsed={'kind':'OPT','udp_size':cls,'ext_rcode':(ttl>>24)&0xff,'version':(ttl>>16)&0xff,'flags':ttl & 0xffff,'data':list(rdata)}
    except Exception:
        parsed={'kind':'raw','bytes':list(rdata)}
    return Record(name, typ, cls, ttl, parsed, section), rend

def parse_response(packet):
    if len(packet)<12: raise ValueError('response too short')
    txid, flags, qd, an, ns, ar = struct.unpack('!HHHHHH', packet[:12])
    rcode = flags & 0x000f
    off=12; queries=[]
    for _ in range(qd):
        name, off=read_name(packet, off)
        if off+4>len(packet): raise ValueError('query truncated')
        qt,qc=struct.unpack('!HH', packet[off:off+4]); off+=4
        queries.append({'name':name,'class':class_display(qc),'type':type_display(qt) if qt in TYPE_NAMES else qt})
    answers=[]; authorities=[]; additionals=[]
    for _ in range(an):
        rec, off=parse_record(packet, off, 'answer'); answers.append(rec)
    for _ in range(ns):
        rec, off=parse_record(packet, off, 'authority'); authorities.append(rec)
    for _ in range(ar):
        rec, off=parse_record(packet, off, 'additional'); additionals.append(rec)
    return {'rcode':rcode,'queries':queries,'answers':answers,'authorities':authorities,'additionals':additionals}

# transports

def read_resolv():
    ns=[]
    try:
        for line in open('/etc/resolv.conf'):
            parts=line.strip().split()
            if len(parts)>=2 and parts[0]=='nameserver': ns.append(parts[1])
    except Exception: pass
    return ns[0] if ns else '127.0.0.1'

def split_host_port(s, default_port):
    if s == '__system__': s=read_resolv()
    if s.startswith('['):
        idx=s.find(']')
        if idx!=-1:
            host=s[1:idx]; rest=s[idx+1:]
            if rest.startswith(':'):
                if not rest[1:].isdigit(): raise NetError('invalid port value')
                return host,int(rest[1:])
            return host,default_port
    if s.count(':')==1:
        host,port=s.rsplit(':',1)
        if port=='': raise NetError('invalid port value')
        if not port.isdigit(): raise NetError('invalid port value')
        return host,int(port)
    return s,default_port

def send_udp(ns, payload):
    host,port=split_host_port(ns,53)
    try:
        sock=socket.socket(socket.AF_INET6 if ':' in host and not host.replace(':','').isdigit() else socket.AF_INET, socket.SOCK_DGRAM)
    except Exception:
        sock=socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.settimeout(5)
        sock.sendto(payload,(host,port))
        data,_=sock.recvfrom(65535)
        return data
    except socket.gaierror:
        raise NetError('failed to lookup address information: Name or service not known')
    except OSError as e:
        raise NetError(format_os_error(e))
    finally:
        try: sock.close()
        except Exception: pass

def recvn(sock,n):
    b=b''
    while len(b)<n:
        c=sock.recv(n-len(b))
        if not c: raise NetError('failed to fill whole buffer')
        b+=c
    return b

def send_tcp(ns,payload,tls=False):
    host,port=split_host_port(ns,853 if tls else 53)
    try:
        raw=socket.create_connection((host,port),timeout=5)
        s=ssl.create_default_context().wrap_socket(raw,server_hostname=host) if tls else raw
        with s:
            s.sendall(struct.pack('!H',len(payload))+payload)
            ln=struct.unpack('!H',recvn(s,2))[0]
            return recvn(s,ln)
    except socket.gaierror:
        raise NetError('failed to lookup address information: Name or service not known')
    except OSError as e:
        raise NetError(format_os_error(e))

def send_https(ns,payload):
    url=ns if ns!='__system__' else read_resolv()
    if not (url.startswith('https://') or url.startswith('http://')):
        # close enough for observed crash-like invalid HTTPS nameserver, but do not panic
        raise NetError('Invalid HTTPS nameserver')
    u=urllib.parse.urlparse(url)
    conn_cls=http.client.HTTPSConnection if u.scheme=='https' else http.client.HTTPConnection
    port=u.port or (443 if u.scheme=='https' else 80)
    path=(u.path or '/') + (('?' + u.query) if u.query else '')
    try:
        conn=conn_cls(u.hostname, port, timeout=5)
        conn.request('POST', path, body=payload, headers={'Content-Type':'application/dns-message','Accept':'application/dns-message'})
        resp=conn.getresponse(); data=resp.read(); conn.close()
        return data
    except socket.gaierror:
        raise NetError('failed to lookup address information: Name or service not known')
    except OSError as e:
        raise NetError(format_os_error(e))

def format_os_error(e):
    if isinstance(e, TimeoutError) or getattr(e,'errno',None) is None and 'timed out' in str(e): return 'timed out'
    eno=getattr(e,'errno',None)
    if eno is not None:
        # os.strerror wording matches observed for common cases
        import os as _os
        return f'{_os.strerror(eno)} (os error {eno})'
    return str(e)

# formatting

def quote(s):
    return json.dumps(s, ensure_ascii=False, separators=(',',':'))

def fmt_dur(sec):
    sec=int(sec)
    if sec < 60: return f'{sec}s'
    m,s=divmod(sec,60)
    if m < 60: return f'{m}m{s:02d}s'
    h,m=divmod(m,60)
    if h < 24: return f'{h}h{m:02d}m{s:02d}s'
    d,h=divmod(h,24)
    return f'{d}d{h}h{m:02d}m{s:02d}s'

def ttl_text(rec,opt):
    if rec.type==41: return ''
    return str(rec.ttl) if opt.seconds else fmt_dur(rec.ttl)

def loc_size_byte(b):
    man=(b>>4)&0xf; exp=b&0xf
    if exp==0: return str(man)
    return f'{man}e{exp}'

def loc_coord(v, positive, negative):
    ref=2**31
    diff=int(v)-ref
    hemi=positive if diff>=0 else negative
    diff=abs(diff)
    # units are thousandths of arc-second
    total_ms=diff
    deg=total_ms//(3600*1000); rem=total_ms%(3600*1000)
    minute=rem//(60*1000); rem%=60*1000
    sec=rem//1000
    return f'{deg}°{minute}′{sec}″ {hemi}'

def loc_alt(v):
    # centimeters above -100000m reference
    cm=int(v)-10000000
    if cm%100==0: return f'{cm//100}m'
    return f'{cm/100:.2f}m'.rstrip('0').rstrip('.')

def record_data_text(rec):
    d=rec.data; k=d.get('kind')
    if k in ('A','AAAA'): return d['address']
    if k=='CNAME': return quote(d['domain'])
    if k=='NS': return quote(d['nameserver'])
    if k=='PTR': return quote(d['cname'])
    if k=='MX': return f"{d['preference']} {quote(d['exchange'])}"
    if k=='SOA': return f"{quote(d['mname'])} {quote(d['rname'])} {d['serial']} {fmt_dur(d['refresh'])} {fmt_dur(d['retry'])} {fmt_dur(d['expire'])} {fmt_dur(d['minimum'])}"
    if k=='SRV': return f"{d['priority']} {d['weight']} {quote(d['target'])}:{d['port']}"
    if k=='TXT': return ', '.join(quote(x) for x in d['messages'])
    if k=='CAA': return f"{quote(d['tag'])} {quote(d['value'])} ({'critical' if d['critical'] else 'non-critical'})"
    if k=='SSHFP': return f"{d['algorithm']} {d['fingerprint_type']} {d['fingerprint']}"
    if k=='TLSA': return f"{d['certificate_usage']} {d['selector']} {d['matching_type']} {quote(d['certificate_data'])}"
    if k=='HINFO': return f"{quote(d['cpu'])} {quote(d['os'])}"
    if k=='NAPTR': return f"{d['order']} {d['preference']} {quote(d['flags'])} {quote(d['service'])} {quote(d['regex'])} {quote(d['replacement'])}"
    if k=='LOC':
        size=loc_size_byte(d.get('size_byte',0)); hp=d.get('hp',0); vp=d.get('vp',0)
        lat=loc_coord(d.get('lat',2**31),'N','S'); lon=loc_coord(d.get('lon',2**31),'E','W'); alt=loc_alt(d.get('alt',10000000))
        return f'{size} ({hp}, {vp}) ({lat}, {lon}, {alt})'
    if k=='OPT': return f"{d.get('udp_size',rec.cls)} {d.get('ext_rcode',0)} {d.get('version',0)} {d.get('flags',0)} {json.dumps(d.get('data',[]), separators=(', ',': '))}"
    return '[' + ', '.join(str(x) for x in d.get('bytes',[])) + ']'

def record_json(rec):
    d=rec.data; k=d.get('kind')
    typ = type_display(rec.type) if rec.type in TYPE_NAMES else rec.type
    if k=='OPT':
        return {'name':rec.name,'type':'OPT','data':{'version':d.get('version',0),'data':d.get('data',[])}}
    obj={'name':rec.name,'class':class_display(rec.cls),'ttl':rec.ttl,'type':typ}
    if k in ('A','AAAA'): data={'address':d['address']}
    elif k=='CNAME': data={'domain':d['domain']}
    elif k=='NS': data={'nameserver':d['nameserver']}
    elif k=='PTR': data={'cname':d['cname']}
    elif k=='MX': data={'preference':d['preference'],'exchange':d['exchange']}
    elif k=='SOA': data={'mname':d['mname']}
    elif k=='SRV': data={'priority':d['priority'],'weight':d['weight'],'port':d['port'],'target':d['target']}
    elif k=='TXT': data={'messages':d['messages']}
    elif k=='CAA': data={'critical':d['critical'],'tag':d['tag'],'value':d['value']}
    elif k=='SSHFP': data={'algorithm':d['algorithm'],'fingerprint_type':d['fingerprint_type'],'fingerprint':d['fingerprint']}
    elif k=='TLSA': data={'certificate_usage':d['certificate_usage'],'selector':d['selector'],'matching_type':d['matching_type'],'certificate_data':d['certificate_data']}
    elif k=='HINFO': data={'cpu':d['cpu'],'os':d['os']}
    elif k=='NAPTR': data={'order':d['order'],'flags':d['flags'],'service':d['service'],'regex':d['regex'],'replacement':d['replacement']}
    elif k=='LOC':
        data={'size':loc_size_byte(d.get('size_byte',0)),'precision':{'horizontal':d.get('hp',0),'vertical':d.get('vp',0)},'point':{'latitude':loc_coord(d.get('lat',2**31),'N','S'),'longitude':loc_coord(d.get('lon',2**31),'E','W'),'altitude':loc_alt(d.get('alt',10000000))}}
    else: data={'bytes':d.get('bytes',[])}
    obj['data']=data; return obj

def output_json(responses,opt):
    arr=[]
    for r in responses:
        adds=[x for x in r['additionals'] if opt.edns=='show' or x.type!=41]
        arr.append({'queries':r['queries'], 'answers':[record_json(x) for x in r['answers']], 'authorities':[record_json(x) for x in r['authorities']], 'additionals':[record_json(x) for x in adds]})
    print(json.dumps({'responses':arr}, separators=(',',':'), ensure_ascii=False))

def output_short(responses):
    lines=[]
    for r in responses:
        for rec in r['answers']:
            if rec.type==41: continue
            lines.append(record_data_text(rec))
    if not lines:
        print('No results', file=sys.stderr); return 2
    print('\n'.join(lines)); return 0

def output_text(responses,opt):
    rows=[]
    for r in responses:
        if r['rcode'] != 0:
            rows.append(('STATUS','Status:', RCODE_TEXT.get(r['rcode'], f'Error {r["rcode"]}'), '', '', ''))
        for secname in ('answers','authorities','additionals'):
            for rec in r[secname]:
                if rec.type==41 and opt.edns!='show': continue
                rows.append(('REC', rec, '', '', '', ''))
    recs=[row[1] for row in rows if row[0]=='REC']
    if recs:
        wtype=max(len(type_display(r.type) if r.type in TYPE_NAMES else str(r.type)) for r in recs)
        wname=max(len(r.name) for r in recs)
        wttl=max(len(ttl_text(r,opt)) for r in recs)
    else:
        wtype=wname=wttl=0
    use_color = (opt.color == 'always') or (opt.color == 'automatic' and sys.stdout.isatty())
    out=[]
    for row in rows:
        if row[0]=='STATUS':
            out.append(f'{row[1]} {row[2]}'); continue
        rec=row[1]
        typ=type_display(rec.type) if rec.type in TYPE_NAMES else str(rec.type)
        name=rec.name; ttl=ttl_text(rec,opt); marker=' '
        if rec.section=='authority': marker='A'
        elif rec.section=='additional': marker='+'
        typ_pad=typ.rjust(wtype); name_pad=name.ljust(wname); ttl_pad=ttl.rjust(wttl)
        if use_color:
            typ_pad=typ_pad.replace(typ, f'\033[1;32m{typ}\033[0m', 1)
            if name:
                name_pad=name_pad.replace(name, f'\033[1;34m{name}\033[0m', 1)
        out.append(f'{typ_pad} {name_pad} {ttl_pad} {marker} {record_data_text(rec)}')
    if out: print('\n'.join(out))
    return 0

def hosts_names():
    names=set()
    try:
        for line in open('/etc/hosts'):
            line=line.split('#',1)[0].strip()
            if not line: continue
            parts=line.split()
            for n in parts[1:]: names.add(normalize_name(n).lower())
    except Exception: pass
    return names

def execute(opt):
    responses=[]; start=time.time(); first_net_err=None
    for domain in opt.domains:
        for qtype in opt.types:
            for qclass in opt.classes:
                payload=build_query(domain,qtype,qclass,opt)
                for ns in opt.nameservers:
                    for tr in opt.transports:
                        try:
                            if tr=='udp': packet=send_udp(ns,payload)
                            elif tr=='tcp': packet=send_tcp(ns,payload,False)
                            elif tr=='tls': packet=send_tcp(ns,payload,True)
                            elif tr=='https': packet=send_https(ns,payload)
                            else: packet=send_udp(ns,payload)
                            responses.append(parse_response(packet))
                        except NetError as e:
                            if first_net_err is None: first_net_err=str(e)
                        except Exception as e:
                            if first_net_err is None: first_net_err=str(e)
    if not responses:
        raise DogError(f'Error [network]: {first_net_err or "network error"}',1)
    if opt.json:
        output_json(responses,opt); rc=0
    elif opt.short:
        rc=output_short(responses)
    else:
        rc=output_text(responses,opt)
    if opt.time and not opt.json and not opt.short:
        print(f'Ran in {int((time.time()-start)*1000)}ms')
    # hosts warning
    hn=hosts_names()
    for d in opt.domains:
        nd=normalize_name(d).lower()
        if nd in hn:
            print(f"warning: domain '{normalize_name(d)}' also exists in hosts file", file=sys.stderr)
    return rc

def main(argv):
    try:
        opt=parse_args(argv)
        return execute(opt)
    except DogError as e:
        if str(e).startswith('Error [network]:'):
            print(str(e), file=sys.stderr); return e.code
        print('dog: Invalid options: ' + str(e), file=sys.stderr); return e.code

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
